        Requested,
        Validated,
        Disbursed,
        Denied,
        Disputed,
        Cancelled,
        Expired
    }

    /**
     * @notice Contains all information about a withdrawal request
     * @dev Struct members:
     * - user: Address of the user who initiated the withdrawal (20 bytes)
